import {companies,jobs,candidates,selectionQuestions,professionalQuestions,initialDB} from './data.js';

const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('it-IT').format(n);
let db;try{db=JSON.parse(localStorage.getItem('mesh-demo-v1'))}catch{}if(!db||db.version!==1)db=initialDB();
let filters={q:'',city:'',mode:'',contract:'',noWeekend:false,min:0};
let jobTab='all',profileTab='overview',appTab='ongoing',companyTab='overview',activeThread='t1',modal=null,companyJob='j1';
let companyCandidateQuery='',chatBusy=false,cvBusy=false,mobileChatOpen=false;
const save=()=>localStorage.setItem('mesh-demo-v1',JSON.stringify(db));
const allJobs=()=>[...db.customJobs,...jobs];
const company=id=>companies.find(c=>c.id===id)||companies[0];
const job=id=>allJobs().find(j=>j.id===id);
const norm=s=>String(s).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
const paths={home:'M3 10l9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z',user:'M20 21v-2a7 7 0 0 0-14 0v2M12 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8',briefcase:'M8 6V4h8v2M3 7h18v14H3zM3 12a24 24 0 0 0 18 0M10 12h4',layers:'M3 7l9-4 9 4-9 4zM3 12l9 4 9-4M3 17l9 4 9-4',message:'M21 11a9 9 0 0 1-9 9H4l-3 3 1-8a9 9 0 1 1 19-4z',arrow:'M5 12h14M13 6l6 6-6 6',arrowUp:'M5 19L19 5M5 5h14v14',search:'M21 21l-5-5M10 17a7 7 0 1 0 0-14 7 7 0 0 0 0 14',pin:'M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0zM12 13a3 3 0 1 0 0-6 3 3 0 0 0 0 6',clock:'M12 8v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8',bookmark:'M6 3h12v19l-6-4-6 4z',spark:'M12 2l2.7 7.3L22 12l-7.3 2.7L12 22l-2.7-7.3L2 12l7.3-2.7z',check:'M5 12l4 4L19 6',close:'M6 6l12 12M18 6L6 18',chevron:'M6 9l6 6 6-6',plus:'M12 4v16M4 12h16',settings:'M4 6h16M7 3v6M4 18h16M17 15v6M4 12h16M12 9v6',file:'M14 2H5v20h14V7zM14 2v6h6M8 12h8M8 16h8',upload:'M12 16V3M7 8l5-5 5 5M3 15v6h18v-6',bell:'M18 8a6 6 0 0 0-12 0c0 8-3 8-3 10h18c0-2-3-2-3-10M10 22h4',chart:'M3 3v18h18M7 16v-4M12 16V7M17 16v-7',building:'M4 22V3h12v19M16 10h5v12M8 7h4M8 11h4M8 15h4M9 22v-3h3v3',logout:'M9 3H3v18h6M12 12h10M18 8l4 4-4 4',send:'M22 2L9 15M22 2l-7 20-6-7-7-6z',eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12M15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0',download:'M12 3v13M7 11l5 5 5-5M4 17v5h16v-5',shield:'M12 2l8 4v6c0 6-8 10-8 10S4 18 4 12V6zM8 12l3 3 5-6',globe:'M22 12H2M12 2c6 7 6 13 0 20-6-7-6-13 0-20M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',menu:'M4 6h16M4 12h16M4 18h16',mail:'M3 5h18v14H3zM3 5l9 8 9-8'};
function icon(name,size=20){return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.spark}"/></svg>`;}
const mark=()=>'<svg class="mesh-mark" viewBox="0 0 32 32" fill="none" aria-hidden="true"><path d="M5 26V6l11 11L27 6v20M5 6h22M5 26h22" stroke="currentColor" stroke-width="1.7"/><circle cx="5" cy="6" r="2.5" fill="currentColor"/><circle cx="27" cy="6" r="2.5" fill="currentColor"/><circle cx="16" cy="17" r="2.5" fill="currentColor"/></svg>';
const brand=()=>`<a class="brand" href="#/">${mark()}<span>mesh<span class="brand-dot">.</span></span></a>`;
function logo(c,size=''){return `<span class="company-logo ${size}" style="--logo-bg:${c.bg};--logo-color:${c.color}">${c.symbol}</span>`;}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
function route(){return location.hash.slice(1)||'/';}
function go(path){if(route()===path)render();else location.hash=path;}
function tag(t,cl=''){return `<span class="tag ${cl}">${esc(t)}</span>`;}
function heart(c){const value=Math.round((c.likes+(db.heart&&c.id==='radice'?1:0))/c.employees*100);return `<button class="heart-summary" data-action="heart-info" data-id="${c.id}" aria-label="Informazioni sugli apprezzamenti di ${c.name}"><span class="heart-shape" style="--fill:${value}%">♥</span><span>${value}% <small>apprezzamenti</small></span></button>`;}
function landing(){return `<div class="landing">
 <header class="public-header">${brand()}<nav aria-label="Navigazione principale"><a href="#companies">Per le aziende</a><a href="#candidates">Per i candidati</a><a href="#how">Il metodo MESH</a></nav><div class="header-actions"><button class="text-button" data-action="login">Accedi</button><a class="button small dark" href="#/jobs">Trova la tua connessione ${icon('arrow',16)}</a></div><button class="mobile-menu icon-button" data-action="login" aria-label="Apri accesso">${icon('menu')}</button></header>
 <main><section class="hero">
  <div class="hero-orbit orbit-one"></div><div class="hero-orbit orbit-two"></div>
  <div class="eyebrow hero-eyebrow"><span class="live-dot"></span> RADICI IN CAMPANIA. ORIZZONTI APERTI.</div>
  <h1>Il talento trova spazio.<br><em>Il lavoro, nuove connessioni.</em></h1>
  <p class="hero-description">Persone e imprese, finalmente sullo stesso piano.<br>Competenze che contano. Condizioni chiare. Possibilità concrete.</p>
  <span class="floating-chip chip-left">${icon('shield',17)} Stipendio in chiaro <span class="tiny-dot"></span></span>
  <span class="floating-chip chip-right"><span class="mini-logo">✳</span> Una nuova possibilità ${icon('arrowUp',15)}</span>
  <div class="hero-cards">
   <article class="path-card company-path" id="companies"><span class="eyebrow">PER LE AZIENDE</span><h2>Il prossimo talento.<br><em>La tua prossima svolta.</em></h2><p>Fai conoscere ciò che offri. Incontra persone<br class="desktop-br"> con le competenze per crescere insieme.</p><a class="button lime" href="#/company">Costruisci il tuo team ${icon('arrow',18)}</a><div class="mini-dashboard"><div class="mini-heading"><span class="live-dot"></span> LA TUA PROSSIMA CONNESSIONE</div><div class="mini-person"><span class="avatar plum">GR</span><span><b>Giulia Romano</b><small>UX/UI Designer · Napoli</small></span><span class="mini-badge">Figma +2</span></div><div class="mini-person"><span class="avatar sand">LE</span><span><b>Luca Esposito</b><small>Visual Designer · Salerno</small></span><span class="mini-badge">Portfolio</span></div></div><div class="card-mesh" aria-hidden="true"></div></article>
   <article class="path-card candidate-path" id="candidates"><span class="eyebrow">PER I CANDIDATI</span><h2>Il tuo prossimo lavoro.<br><em>Alle tue condizioni.</em></h2><p>Scopri chi cerca proprio te. Conosci stipendio,<br class="desktop-br"> turni e prospettive, prima di fare il primo passo.</p><a class="button dark" href="#/jobs">Esplora le opportunità ${icon('arrow',18)}</a><div class="mini-dashboard light"><div class="mini-heading">IL TUO TALENTO, NEL POSTO GIUSTO</div><div class="mini-job">${logo(companies[0],'mini')}<span><b>Junior UX/UI Designer</b><small>radice studio · Salerno · Ibrido</small></span><b class="mini-salary">26–32k €</b></div><div class="mini-job">${logo(companies[1],'mini')}<span><b>Frontend Developer</b><small>orbit digital · Napoli · Ibrido</small></span><b class="mini-salary">32–40k €</b></div></div></article>
  </div>
 </section>
 <section class="company-ribbon"><div class="eyebrow">PICCOLE E MEDIE IMPRESE. GRANDI POSSIBILITÀ.</div><div class="marquee" aria-label="Esempi di aziende dell'archivio dimostrativo"><div class="marquee-track">${[...companies,...companies,...companies].map(c=>`<div class="marquee-logo"><span style="color:${c.color}">${c.symbol}</span><b>${c.name}</b><small>${c.suffix}</small></div>`).join('')}</div></div><p>Aziende e opportunità illustrate sono esempi dimostrativi.</p></section>
 <section class="manifesto" id="how"><div><span class="eyebrow">PIÙ CHIAREZZA. MENO DISTANZA.</span><h2>Non solo un incontro.<br><em>Un buon punto di partenza.</em></h2><p>MESH è la rete che avvicina ciò che sai fare<br>a ciò che puoi diventare.</p><a href="#/jobs" class="inline-link">Trova il tuo spazio ${icon('arrow')}</a></div><div class="principle-list"><article><span>01</span><div><h3>Sai a cosa vai incontro.</h3><p>Compenso, turni e modalità di lavoro. Le informazioni importanti, subito.</p></div>${icon('arrowUp')}</article><article><span>02</span><div><h3>Il tuo percorso vale.</h3><p>L’AI ti aiuta a raccontare competenze, esperienze e ciò che ti rende unico.</p></div>${icon('arrowUp')}</article><article><span>03</span><div><h3>Vedi dove puoi arrivare.</h3><p>Ruoli futuri, formazione e prospettive economiche, con condizioni esplicite.</p></div>${icon('arrowUp')}</article></div></section>
 <section class="bottom-cta"><span class="eyebrow">IL PROSSIMO PASSO PARTE DA UNA CONNESSIONE.</span><h2>Fai spazio al tuo <em>possibile.</em></h2><a class="button lime" href="#/jobs">Entra in MESH ${icon('arrow')}</a><div class="cta-nodes" aria-hidden="true">${mark()}</div></section></main>
 <footer class="public-footer">${brand()}<span>Talento e imprese. A condizioni chiare.</span><div><button class="text-button" data-action="about">Il progetto</button><span class="demo-label">Prototipo · dati fittizi</span></div></footer></div>`;}

function shell(content,section,isCompany=false){const nav=isCompany?[['overview','Panoramica','chart'],['offers','Offerte','briefcase'],['talents','Talenti','user'],['selections','Selezioni','layers'],['messages','Messaggi','message'],['business','Azienda','building']]:[['home','Home','home'],['profile','Profile','user'],['jobs','Jobs','briefcase'],['applied','Applied','layers'],['messages','Messages','message']];return `<div class="app-layout ${isCompany?'business-layout':''}"><aside class="sidebar">${brand()}<div class="sidebar-label">${isCompany?'WORKSPACE':'IL TUO SPAZIO'}</div><nav aria-label="${isCompany?'Area azienda':'Area candidato'}">${nav.map(([id,text,ico])=>`<a class="side-link ${section===id?'active':''}" href="#/${isCompany?'company/'+id:id}">${icon(ico,22)}<span>${text}</span>${id==='messages'?'<i class="notification-dot"></i>':''}</a>`).join('')}</nav><div class="sidebar-bottom">${!isCompany?`<a href="#/plus" class="side-link plus-link ${section==='plus'?'active':''}">${icon('spark',21)}<span>MESH Plus</span></a>`:''}<button class="side-link" data-action="switch"><span class="switch-icon">${icon(isCompany?'user':'building',20)}</span><span>Passa ${isCompany?'a candidato':'ad azienda'}</span></button><div class="side-account"><span class="avatar ${isCompany?'sage':'plum'}">${isCompany?'rs':esc(db.profile.name.split(' ').map(w=>w[0]).join('').slice(0,2))}</span><span><b>${isCompany?'radice studio':esc(db.profile.name)}</b><small>${isCompany?'Workspace azienda':'Profilo candidato'}</small></span></div></div></aside><div class="workspace"><header class="workspace-header"><div><span class="breadcrumb">${isCompany?'PER LE AZIENDE':'PER I CANDIDATI'}</span><span class="header-separator">/</span><span>${nav.find(x=>x[0]===section)?.[1]||'MESH Plus'}</span></div><div class="workspace-tools"><span class="demo-label"><span class="live-dot"></span> DEMO INTERATTIVA</span><button class="icon-button" data-action="notifications" aria-label="Notifiche">${icon('bell')}</button><button class="icon-button" data-action="reset" aria-label="Ripristina dati demo">${icon('settings')}</button><span class="avatar tiny ${isCompany?'sage':'plum'}">${isCompany?'rs':'GR'}</span></div></header><main class="workspace-main">${content}</main><footer class="workspace-footer"><span>MESH · Il tuo talento, la giusta connessione.</span><span>Archivio demo locale · nessun dato reale</span></footer></div></div>`;}
function pageHead(eyebrow,title,desc='',action=''){return `<div class="page-heading"><div><span class="eyebrow">${eyebrow}</span><h1>${title}</h1>${desc?`<p>${desc}</p>`:''}</div>${action}</div>`;}
function jobCard(j){const c=company(j.company);const applied=db.applications.some(a=>a.jobId===j.id);return `<article class="job-card"><div class="job-card-top">${logo(c)}<div class="company-info"><b>${esc(c.name)} <span>${esc(c.suffix)}</span></b><small>${esc(c.sector)} · ${c.employees} persone</small></div><button class="icon-button save-job ${db.saved.includes(j.id)?'saved':''}" data-action="save-job" data-id="${j.id}" aria-label="${db.saved.includes(j.id)?'Rimuovi dai salvati':'Salva offerta'}" aria-pressed="${db.saved.includes(j.id)}">${icon('bookmark')}</button></div><a class="job-title" href="#/job/${j.id}"><h2>${esc(j.title)}</h2>${icon('arrowUp',22)}</a><div class="job-meta"><span>${icon('pin',15)} ${esc(j.city)} · ${esc(j.mode)}</span><span>${icon('clock',15)} ${j.hours}h · ${esc(j.contract)}</span></div><div class="job-salary"><b>${money(j.salary[0])}–${money(j.salary[1])} €</b><span>lordi / anno</span><span class="salary-check">${icon('check',13)} In chiaro</span></div><div class="job-tags">${j.tags.map(t=>tag(t)).join('')}${!j.weekend?tag('No weekend','subtle'):''}</div><div class="job-card-bottom"><span>${esc(j.posted)} <span class="dot-separator">·</span> ${applied?'Candidatura inviata':'Candidatura diretta'}</span><a href="#/job/${j.id}" class="job-discover">${applied?'Vedi candidatura':'Scopri il ruolo'} ${icon('arrow',16)}</a></div></article>`;}
function filteredJobs(){return allJobs().filter(j=>{const c=company(j.company);return(!filters.q||norm(j.title+' '+j.category+' '+c.name+' '+j.skills.join(' ')).includes(norm(filters.q)))&&(!filters.city||j.city===filters.city)&&(!filters.mode||j.mode===filters.mode)&&(!filters.contract||j.contract===filters.contract)&&(!filters.noWeekend||!j.weekend)&&j.salary[1]>=filters.min&&(jobTab!=='saved'||db.saved.includes(j.id))&&(jobTab==='hidden'?db.hidden.includes(j.id):!db.hidden.includes(j.id));});}
function chatPanel(){return `<aside class="search-assistant panel ${mobileChatOpen?'mobile-open':''}"><div class="assistant-head"><span class="ai-icon">${icon('spark',21)}</span><div><b>Troviamolo, insieme.</b><small>Il tuo assistente di ricerca</small></div><span class="ai-status"></span></div><button class="mobile-ai-toggle" data-action="mobile-chat">${mobileChatOpen?'Chiudi assistente':'Descrivi il lavoro che cerchi'} ${icon(mobileChatOpen?'close':'arrow',15)}</button><div class="assistant-intro"><h3>Il prossimo passo<br>inizia da <em>te.</em></h3><p>Raccontami il lavoro che immagini.<br>Trasformiamo le tue idee in opportunità.</p></div><div class="chat-messages" id="search-chat">${db.searchMessages.length?db.searchMessages.map(m=>`<div class="chat-message ${m.role}">${esc(m.text)}</div>`).join(''):`<div class="chat-message assistant">Ciao Giulia! Quale lavoro ti farebbe dire: «è il posto giusto per me»?</div>`}</div>${!db.searchMessages.length?`<div class="suggestion-list"><button data-action="suggest" data-text="Cerco un lavoro di design a Salerno, possibilmente ibrido">${icon('arrowUp',14)} Design a Salerno</button><button data-action="suggest" data-text="Vorrei un lavoro da remoto senza weekend">${icon('arrowUp',14)} Remoto, senza weekend</button><button data-action="suggest" data-text="Cerco un ruolo in amministrazione">${icon('arrowUp',14)} Un ruolo amministrativo</button></div>`:''}<form id="search-chat-form" class="chat-input"><textarea name="message" rows="2" placeholder="Scrivi quello che cerchi…" aria-label="Parla con l'assistente di ricerca" required></textarea><button class="send-button" type="submit" aria-label="Invia messaggio">${icon('arrow',18)}</button></form><div class="ai-disclaimer">${icon('spark',12)} Modalità demo · Gemini da collegare</div><button class="text-button chat-reset" data-action="clear-search">Ricomincia la ricerca</button></aside>`;}
function jobsPage(){const list=filteredJobs();return shell(`${pageHead('LE OPPORTUNITÀ, A MODO TUO.','Trova il tuo <em>prossimo passo.</em>','Condizioni in chiaro. Persone al centro. Nessuna sorpresa.')}<div class="jobs-layout"><div class="jobs-main"><div class="tabs job-tabs"><button data-action="job-tab" data-tab="all" class="${jobTab==='all'?'active':''}">Tutte le offerte <span>${allJobs().length-db.hidden.length}</span></button><button data-action="job-tab" data-tab="saved" class="${jobTab==='saved'?'active':''}">Salvate <span>${db.saved.length}</span></button><button data-action="job-tab" data-tab="hidden" class="${jobTab==='hidden'?'active':''}">Nascoste <span>${db.hidden.length}</span></button></div><div class="search-filters panel"><div class="search-fields"><label class="search-control">${icon('search',19)}<input id="job-query" aria-label="Ruolo o competenza" placeholder="Ruolo, competenza o azienda" value="${esc(filters.q)}"></label><label class="search-control">${icon('pin',19)}<select id="job-city" aria-label="Località"><option value="">Tutta la Campania</option>${['Napoli','Salerno','Caserta','Avellino','Benevento'].map(c=>`<option ${filters.city===c?'selected':''}>${c}</option>`).join('')}</select></label></div><div class="filter-row"><select id="job-mode" aria-label="Modalità"><option value="">Modalità di lavoro</option>${['Ibrido','Remoto','In sede'].map(x=>`<option ${filters.mode===x?'selected':''}>${x}</option>`).join('')}</select><select id="job-contract" aria-label="Contratto"><option value="">Tipo di contratto</option>${['Indeterminato','Apprendistato','Determinato'].map(x=>`<option ${filters.contract===x?'selected':''}>${x}</option>`).join('')}</select><button class="filter-toggle ${filters.noWeekend?'selected':''}" data-action="weekend">${filters.noWeekend?icon('check',14):icon('plus',14)} No weekend</button><button class="icon-button" data-action="clear-filters" aria-label="Azzera filtri">${icon('settings',17)}</button></div>${filters.min?`<div class="active-filter">Da ${money(filters.min)} € lordi/anno <button data-action="clear-min" aria-label="Rimuovi soglia">×</button></div>`:''}</div><div class="results-heading"><span><b>${list.length}</b> opportunità ${jobTab==='saved'?'salvate':'per te'}</span><span class="muted">Più recenti ${icon('chevron',14)}</span></div><div class="job-list">${list.length?list.map(jobCard).join(''):`<div class="empty-state panel">${icon('search',35)}<h2>La connessione giusta richiede spazio.</h2><p>Nessuna offerta corrisponde a tutti i filtri. Puoi modificarli: i tuoi vincoli non saranno cambiati automaticamente.</p><button class="button dark" data-action="clear-filters">Rivedi i filtri ${icon('arrow',16)}</button></div>`}</div></div>${chatPanel()}</div>`, 'jobs');}
function jobDetail(id){const j=job(id);if(!j)return shell(empty('Offerta non trovata','Torna alla ricerca delle opportunità.','/jobs'),'jobs');const c=company(j.company),applied=db.applications.some(a=>a.jobId===id);return shell(`<a class="back-link" href="#/jobs">← Tutte le opportunità</a><div class="detail-layout"><div><article class="panel detail-hero"><div class="job-card-top">${logo(c,'large')}<div><span class="eyebrow">${esc(c.name)} ${esc(c.suffix)}</span><div class="job-meta">${esc(c.sector)} · ${c.employees} dipendenti</div></div><button class="icon-button ${db.saved.includes(id)?'saved':''}" data-action="save-job" data-id="${id}" aria-label="Salva offerta">${icon('bookmark')}</button></div><h1>${esc(j.title)}</h1><div class="job-meta"><span>${icon('pin',17)} ${esc(j.city)}</span><span>${icon('globe',17)} ${esc(j.mode)}</span><span>${icon('clock',17)} ${j.hours}h settimanali</span></div><div class="conditions-grid"><div><small>RETRIBUZIONE ANNUA LORDA</small><b>${money(j.salary[0])}–${money(j.salary[1])} €</b></div><div><small>CONTRATTO</small><b>${esc(j.contract)}</b></div><div><small>TURNI E ORARI</small><b>${esc(j.shift)}</b></div><div><small>MODALITÀ</small><b>${esc(j.mode)}${!j.weekend?' · nessun weekend':''}</b></div></div></article><section class="panel detail-section"><span class="eyebrow">IL RUOLO, SENZA GIRI DI PAROLE.</span><h2>Di cosa ti occuperai</h2><p>${esc(j.description)}</p><ul class="check-list">${j.tasks.map(t=>`<li>${icon('check',17)} ${esc(t)}</li>`).join('')}</ul><h3>Le capacità che porti con te</h3><div class="job-tags">${j.skills.map(s=>tag(s,db.profile.skills.some(x=>norm(x)===norm(s))?'match':'')).join('')}</div><p class="small-copy">Le competenze dichiarate nel profilo sono distinte dalle capacità documentate o verificate.</p></section><section class="panel detail-section"><span class="eyebrow">NON SOLO DOVE INIZI. DOVE PUOI ARRIVARE.</span><h2>Spazio per crescere</h2><div class="growth-path"><article><span class="growth-node current"></span><small>IL TUO PUNTO DI PARTENZA</small><h3>${esc(j.title)}</h3><b>${money(j.salary[0])}–${money(j.salary[1])} € RAL</b></article>${j.growth.map((g,i)=>`<article><span class="growth-node"></span><small>PASSO ${i+1}</small><h3>${esc(g[0])}</h3><b>${esc(g[1])} RAL</b><p>${esc(g[2])}</p></article>`).join('')}</div><div class="info-note">${icon('shield',18)} Percorso indicativo demo: avanzamenti subordinati a competenze, risultati concordati e disponibilità della posizione.</div></section><section class="panel detail-section"><span class="eyebrow">LE TUE COMPETENZE, IN PROSPETTIVA.</span><h2>Il tuo punto di incontro</h2>${j.skills.map(s=>{const has=db.profile.skills.some(x=>norm(x)===norm(s));return `<div class="skill-row"><span>${esc(s)}</span>${tag(has?'Dichiarata nel tuo profilo':'Da approfondire',has?'match':'')}</div>`}).join('')}<div class="learning-card">${icon('spark',24)}<div><b>Ogni passo si può imparare.</b><p>Esplora un laboratorio demo sulle competenze del ruolo. Materiali reali da verificare prima della pubblicazione.</p></div><button class="inline-link" data-action="learning" data-id="${id}">Esplora ${icon('arrow',17)}</button></div></section></div><aside class="detail-side"><section class="panel apply-panel"><span class="eyebrow">IL TUO PROSSIMO PASSO</span><h3>Ti ci vedi?</h3><p>Condividi il tuo profilo e inizia una conversazione.</p><button class="button dark wide" data-action="${applied?'view-application':'apply'}" data-id="${id}">${applied?'Vedi candidatura':'Candidati a questo ruolo'} ${icon('arrow',18)}</button><small>${icon('shield',14)} Il CV viene condiviso solo quando confermi.</small></section><section class="panel salary-panel"><span class="eyebrow">UNO SGUARDO AL MERCATO</span><h3>${money(j.benchmark[0])}–${money(j.benchmark[1])} €</h3><p>Fascia orientativa lorda annuale<br>per un ruolo simile.</p><div class="salary-line"><span></span><i></i></div><small>Dati fittizi · ottobre 2026<br>Non è una rilevazione salariale reale.</small></section><section class="panel company-about"><div class="job-card-top">${logo(c)}<b>${esc(c.name)} ${esc(c.suffix)}</b></div><p>${esc(c.about)}</p>${heart(c)}<div class="job-tags">${c.benefits.map(b=>tag(b)).join('')}</div></section><button class="text-button hide-offer" data-action="hide-job" data-id="${id}">${db.hidden.includes(id)?'Mostra di nuovo':'Nascondi questa offerta'}</button></aside></div>`,'jobs');}
function empty(title,desc,path){return `<div class="empty-state panel">${icon('layers',32)}<h2>${title}</h2><p>${desc}</p><a href="#${path}" class="button dark">Esplora ${icon('arrow')}</a></div>`;}

function profilePage(){return shell(`${pageHead('IL TUO PERCORSO MERITA SPAZIO.','Molto più di <em>un curriculum.</em>','Racconta chi sei. Mostra ciò che puoi diventare.',`<button class="button outline small" data-action="public-profile">${icon('eye',17)} Anteprima profilo</button>`)}<div class="tabs profile-tabs">${[['overview','Overview'],['personal','Profile'],['cv','Resume / CV']].map(([id,t])=>`<button data-action="profile-tab" data-tab="${id}" class="${profileTab===id?'active':''}">${t}${id==='cv'?`<span class="tab-ai">${icon('spark',12)} AI</span>`:''}</button>`).join('')}</div>${profileTab==='personal'?personalProfile():profileTab==='cv'?cvProfile():overviewProfile()}`,'profile');}
function overviewProfile(){const p=db.profile;return `<div class="profile-overview-grid"><article class="panel profile-preview"><div class="profile-cover"><div class="cover-mesh"></div><span>IL TUO TALENTO, IN PRIMO PIANO.</span></div><div class="profile-body"><span class="avatar profile-avatar plum">${esc(p.name.split(' ').map(w=>w[0]).join('').slice(0,2))}</span><span class="profile-availability"><span class="live-dot"></span> ${p.visible?'Aperta alle opportunità':'Profilo riservato'}</span><h2>${esc(p.name)}</h2><p class="profile-title">${esc(p.title)}</p><div class="job-meta"><span>${icon('pin',16)} ${esc(p.city)}</span><span>${icon('briefcase',16)} ${esc(p.experience)} di esperienza</span></div><h3>In poche parole</h3><p>${esc(p.bio)}</p><h3>Ciò che porto nel team</h3><div class="job-tags">${p.skills.map(s=>tag(s,'match')).join('')}</div><h3>Il mio prossimo passo</h3><p>${esc(p.aspirations)}</p><div class="profile-expectations"><div><small>ASPETTATIVA ECONOMICA</small><b>${esc(p.salary)}</b></div><div><small>DISPONIBILITÀ</small><b>${esc(p.availability)}</b></div></div><h3>Formazione</h3><p>${esc(p.education)}</p></div></article><aside><section class="panel completeness-card"><span class="eyebrow">UN PROFILO CHE TI SOMIGLIA</span><div class="complete-circle">${p.bio&&p.skills.length?85:50}<small>%</small></div><h3>Sei sulla buona strada.</h3><p>Aggiungi esempi concreti al CV per dare più forza alle tue capacità.</p><button class="button dark wide" data-action="profile-tab" data-tab="cv">Completa con l’AI ${icon('spark',17)}</button></section><section class="panel profile-side-note">${icon('shield',23)}<h3>Tu scegli cosa condividere.</h3><p>Il racconto personale usato con l’assistente resta distinto dal profilo mostrato alle aziende.</p><button class="inline-link" data-action="profile-tab" data-tab="personal">Gestisci il profilo ${icon('arrow',16)}</button></section><a class="boost-teaser" href="#/plus"><span>${icon('spark',20)} MESH PLUS</span><h3>Più spazio<br>al tuo talento.</h3><p>Scopri la visibilità sponsorizzata.</p><b>20 € / mese ${icon('arrow',18)}</b></a></aside></div>`;}
function personalProfile(){const p=db.profile;return `<form id="profile-form" class="panel form-panel"><div class="section-heading"><div><h2>Le informazioni che ti raccontano</h2><p>Puoi modificarle quando vuoi.</p></div>${icon('user',26)}</div><div class="form-grid">${[['name','Nome e cognome',p.name],['title','Titolo professionale',p.title],['city','Città',p.city],['email','Email di contatto',p.email],['experience','Esperienza',p.experience],['education','Formazione',p.education]].map(([n,l,v])=>`<label>${l}<input name="${n}" value="${esc(v)}" ${n==='email'?'type="email"':''} required></label>`).join('')}<label class="full">Presentazione<textarea name="bio" rows="3">${esc(p.bio)}</textarea></label><label class="full">Competenze, separate da virgole<input name="skills" value="${esc(p.skills.join(', '))}"></label></div><label class="checkbox-label"><input type="checkbox" name="visible" ${p.visible?'checked':''}> Rendi il profilo disponibile nella ricerca delle aziende demo</label><div class="form-footer"><span class="small-copy">Dati conservati solo in questo browser per la demo.</span><button class="button dark" type="submit">Salva il profilo ${icon('check',17)}</button></div></form>`;}
function cvProfile(){const p=db.profile;return `<div class="cv-layout"><section class="panel cv-assistant"><div class="assistant-head"><span class="ai-icon">${icon('spark',21)}</span><div><b>La tua storia, le tue parole.</b><small>Il tuo CV prende forma, insieme a te.</small></div></div><div class="cv-chat-intro"><h2>Tu racconta.<br><em>Al CV pensiamo insieme.</em></h2><p>Esperienze di lavoro, studi, progetti e vita quotidiana. Anche le capacità che non sapevi come raccontare.</p></div><div class="chat-message assistant">${db.cvDraft?'Ho preparato una bozza basata sul tuo racconto. Controllala e correggila prima di salvarla: non ho aggiunto titoli o esperienze non dichiarati.':'Da dove vuoi iniziare? Raccontami cosa hai fatto, cosa hai imparato e quale lavoro immagini per te.'}</div><form id="cv-chat-form"><textarea class="story-input" name="story" rows="7" placeholder="Per esempio: ho studiato design, ho curato la comunicazione di un’associazione e mi piace capire come rendere più semplici le cose…" required>${esc(db.cvMessages.at(-1)||'')}</textarea><div class="cv-context"><label>Cosa cerchi nel prossimo lavoro?<textarea name="aspirations" rows="2">${esc(p.aspirations)}</textarea></label><div class="form-grid"><label>Compenso desiderato<input name="salary" value="${esc(p.salary)}"></label><label>Orari e disponibilità<input name="availability" value="${esc(p.availability)}"></label></div></div><button class="button dark wide" type="submit">${icon('spark',17)} ${db.cvDraft?'Aggiorna la bozza':'Crea la mia bozza CV'}</button></form><div class="ai-disclaimer">Simulazione guidata · integrazione Gemini non ancora attiva</div><label class="upload-text">${icon('upload',17)} Parti da un testo esistente (.txt)<input id="cv-upload" type="file" accept=".txt,text/plain" hidden></label></section><section class="panel resume-preview" id="resume-print"><div class="resume-toolbar"><span class="eyebrow">${db.cvDraft?'BOZZA DA REVISIONARE':'ANTEPRIMA DEL TUO CV'}</span><button class="icon-button" data-action="print-cv" aria-label="Stampa o salva PDF">${icon('download',19)}</button></div><div class="resume-content"><div class="resume-brand">MESH / CURRICULUM VITAE</div><h2>${esc(p.name)}</h2><p class="resume-profession">${esc(p.title)}</p><p class="resume-contact">${esc(p.city)} · ${esc(p.email)}</p><h4>PROFILO</h4><textarea id="cv-summary" rows="6" aria-label="Rivedi il profilo del CV">${esc(db.cvDraft?.summary||p.bio)}</textarea><h4>COMPETENZE DICHIARATE</h4><div class="job-tags">${(db.cvDraft?.skills||p.skills).map(s=>tag(s)).join('')}</div><h4>FORMAZIONE</h4><p>${esc(p.education)}</p><h4>OBIETTIVO PROFESSIONALE</h4><p>${esc(db.cvDraft?.aspirations||p.aspirations)}</p><div class="resume-evidence">${icon('shield',16)} Le informazioni sono dichiarate dalla persona. La demo non verifica attestati o competenze.</div></div><div class="resume-save"><button class="button dark wide" data-action="save-cv">Conferma e salva il CV ${icon('check',17)}</button><button class="text-button" data-action="download-cv">Esporta i dati del CV</button></div></section></div>`;}

function applicationsPage(){const list=db.applications.filter(a=>appTab==='archived'?['Non selezionata','Ritirata','Assunta'].includes(a.status):!['Non selezionata','Ritirata','Assunta'].includes(a.status));return shell(`${pageHead('OGNI PASSO, SEMPRE IN CHIARO.','Le tue <em>connessioni.</em>','Segui le candidature, dai primi contatti al prossimo capitolo.')}<div class="tabs"><button class="${appTab==='ongoing'?'active':''}" data-action="app-tab" data-tab="ongoing">In corso <span>${db.applications.filter(a=>!['Non selezionata','Ritirata','Assunta'].includes(a.status)).length}</span></button><button class="${appTab==='archived'?'active':''}" data-action="app-tab" data-tab="archived">Archiviate</button><button data-action="employment">Il mio rapporto demo ${icon('heart',15)}</button></div><div class="applications-list">${list.length?list.map(a=>{const j=job(a.jobId),c=company(j.company);return `<article class="panel application-card"><div class="job-card-top">${logo(c)}<div><h3>${esc(j.title)}</h3><p>${esc(c.name)} ${esc(c.suffix)} · ${esc(j.city)}</p></div>${tag(a.status,'match')}</div><div class="application-track">${['Inviata','Profilo letto','Colloquio','Proposta'].map((s,i)=>`<span class="${i<=(a.status==='Colloquio'?2:a.status==='Proposta'?3:0)?'done':''}"><i></i>${s}</span>`).join('')}</div><div class="job-card-bottom"><span>Inviata il ${new Date(a.date).toLocaleDateString('it-IT')} · versione dell’offerta conservata</span><div class="button-group"><button class="text-button" data-action="feedback" data-id="${a.id}">${db.feedbacks[a.id]?'Feedback salvato':'Valuta la selezione'}</button><a class="button outline small" href="#/messages">Apri conversazione ${icon('arrow',16)}</a>${!['Ritirata','Assunta','Non selezionata'].includes(a.status)?`<button class="icon-button" data-action="withdraw" data-id="${a.id}" aria-label="Ritira candidatura">${icon('close',17)}</button>`:''}</div></div></article>`}).join(''):empty('Il prossimo incontro ti aspetta.','Esplora le offerte e trova una possibilità da cui partire.','/jobs')}</div>`,'applied');}
function messagesPage(isCompany=false){const thread=db.threads.find(t=>t.id===activeThread)||db.threads[0];const c=company(thread.company);return shell(`${pageHead('LE CONNESSIONI INIZIANO PARLANDO.','Una conversazione,<em> nuove possibilità.</em>')}<div class="messages-layout panel"><aside class="thread-list"><h3>Messaggi <span>${db.threads.length}</span></h3>${db.threads.map(t=>{const co=company(t.company);return `<button class="thread-item ${t.id===thread.id?'active':''}" data-action="thread" data-id="${t.id}">${isCompany?'<span class="avatar plum">GR</span>':logo(co)}<span><b>${isCompany?esc(db.profile.name):esc(co.name+' '+co.suffix)}</b><small>${esc(t.messages.at(-1)?.text||'Inizia una conversazione')}</small></span><i class="notification-dot"></i></button>`}).join('')}</aside><section class="conversation"><header><div>${isCompany?'<span class="avatar plum">GR</span>':logo(c)}<span><b>${isCompany?esc(db.profile.name):esc(c.name+' '+c.suffix)}</b><small>Junior UX/UI Designer · conversazione demo</small></span></div><span class="tag match">Conversazione diretta</span></header><div class="conversation-body"><div class="day-divider">OGGI · DATI DIMOSTRATIVI</div>${thread.messages.map(m=>`<div class="message-row ${m.from===(isCompany?'company':'candidate')?'outgoing':'incoming'}"><div class="message-bubble">${esc(m.text)}<small>${esc(m.time)}</small></div></div>`).join('')}</div><form class="message-form" id="message-form"><textarea rows="2" name="message" placeholder="Scrivi un messaggio…" aria-label="Messaggio" required></textarea><button class="button dark" type="submit">Invia ${icon('send',17)}</button></form><small class="conversation-disclaimer">I messaggi rimangono nell’archivio locale di questa demo.</small></section></div>`,isCompany?'messages':'messages',isCompany);}
function homePage(){return shell(`${pageHead('BENTORNATA, GIULIA.','C’è spazio per il tuo <em>prossimo passo.</em>','Le opportunità iniziano quando il tuo talento incontra le condizioni giuste.')}<div class="home-grid"><a href="#/jobs" class="home-main-card"><span class="eyebrow">IL PROSSIMO CAPITOLO</span><h2>Un lavoro che<br>ti faccia <em>crescere.</em></h2><p>${allJobs().length} opportunità dimostrative da esplorare.</p><span class="button lime">Trova la tua connessione ${icon('arrow')}</span><div class="home-mesh">${mark()}</div></a><section class="panel home-activity"><span class="eyebrow">IL TUO PERCORSO</span><a href="#/applied"><b>${db.applications.length}</b><span>Candidature inviate</span>${icon('arrow',18)}</a><a href="#/jobs" data-action="saved-link"><b>${db.saved.length}</b><span>Offerte salvate</span>${icon('arrow',18)}</a><a href="#/messages"><b>${db.threads.length}</b><span>Conversazioni</span>${icon('arrow',18)}</a></section></div><div class="section-heading"><div><span class="eyebrow">UNO SGUARDO ALLE POSSIBILITÀ</span><h2>Da dove vuoi cominciare?</h2></div><a class="inline-link" href="#/jobs">Tutte le offerte ${icon('arrow',17)}</a></div><div class="home-job-grid">${allJobs().slice(0,2).map(jobCard).join('')}</div>`,'home');}
function plusPage(){return shell(`${pageHead('IL TUO TALENTO, UN PO’ PIÙ VISIBILE.','Fai spazio a <em>nuove connessioni.</em>','La visibilità in più è una scelta. Il valore delle tue competenze resta tuo.')}<div class="plus-layout"><section class="plus-story"><span class="eyebrow">MESH PLUS</span><h2>Le capacità sono tue.<br>Lo spazio in più,<br><em>lo scegli tu.</em></h2><p>Metti il tuo profilo in evidenza nelle ricerche pertinenti delle aziende. Con una sponsorizzazione riconoscibile, senza cambiare chi sei.</p><div class="sponsored-example"><span class="avatar plum">GR</span><div><b>${esc(db.profile.name)}</b><small>${esc(db.profile.title)}</small></div>${tag('Sponsorizzato','sponsored')}</div><p class="small-copy">La sponsorizzazione rispetta i filtri aziendali e la visibilità autorizzata. Non aumenta le valutazioni e non garantisce colloqui o assunzioni.</p></section><section class="panel price-card"><span class="eyebrow">PIÙ VISIBILITÀ. STESSA TRASPARENZA.</span><h3>MESH Plus ${icon('spark',24)}</h3><div class="price">20 €<small>/ mese</small></div><ul class="check-list"><li>${icon('check')}Profilo in evidenza nelle ricerche pertinenti</li><li>${icon('check')}Badge di sponsorizzazione trasparente</li><li>${icon('check')}Controllo della visibilità del tuo profilo</li><li>${icon('check')}Ricerca e candidature standard disponibili</li></ul><button class="button dark wide" data-action="boost">${db.boost?'Disattiva la sponsorizzazione demo':'Prova MESH Plus nella demo'} ${icon('arrow',18)}</button><small>Nessun pagamento reale. Nessuna carta richiesta.<br>${db.boost?'Sponsorizzazione demo attiva.':'Abbonamento e rinnovi sono simulati.'}</small>${!db.profile.visible?'<div class="info-note">Il tuo profilo è riservato: il boost non lo renderà visibile automaticamente.</div>':''}</section></div>`,'plus');}

function companyPage(section='overview'){companyTab=section;if(section==='messages')return messagesPage(true);if(section==='offers')return companyOffers();if(section==='talents')return companyTalents();if(section==='selections')return companySelections();if(section==='business')return companyBusiness();return shell(`${pageHead('IL TUO TEAM, IL TUO PROSSIMO CAPITOLO.','Buongiorno, <em>radice.</em>','Le persone giuste, le condizioni per crescere insieme.',`<button class="button dark" data-action="new-offer">${icon('plus',17)} Pubblica un’offerta</button>`)}<div class="business-stats">${[['Offerte attive',allJobs().filter(j=>j.company==='radice').length,'briefcase'],['Candidature',candidates.length,'user'],['Colloqui in programma',1+db.calendar.length,'message'],['Apprezzamenti',`${Math.round((12+(db.heart?1:0))/24*100)}%`,'heart']].map(([l,n,i])=>`<div class="panel stat-card"><span>${l}${icon(i,20)}</span><b>${n}</b><small>Archivio dimostrativo</small></div>`).join('')}</div><div class="business-overview-grid"><section class="panel business-candidates"><div class="section-heading"><div><span class="eyebrow">PERSONE, PRIMA DEI PROFILI.</span><h2>Nuove connessioni</h2></div><a href="#/company/selections" class="inline-link">Vedi tutte ${icon('arrow',16)}</a></div>${candidates.slice(0,3).map(c=>candidateRow(c)).join('')}</section><section class="business-tip"><span class="eyebrow">LA TRASPARENZA ATTIRA TALENTO.</span><h2>Racconta cosa offri.<br><em>Fai vedere dove si cresce.</em></h2><p>Un’offerta chiara dà alle persone un motivo concreto per scegliere il tuo team.</p><a class="button lime small" href="#/company/offers">Rivedi le tue offerte ${icon('arrow',17)}</a><div class="tip-mesh">${mark()}</div></section></div><section class="panel next-steps"><div><span class="eyebrow">IL PROSSIMO INCONTRO</span><h3>Conoscere Giulia, oltre il curriculum.</h3><p>UX/UI Designer · Primo colloquio conoscitivo</p></div><button class="button outline" data-action="schedule">${icon('clock',18)} Organizza un incontro</button></section>`,'overview',true);}
function candidateRow(c){const isSponsored=c.sponsored||(c.id==='c1'&&db.boost&&db.profile.visible);return `<article class="candidate-row"><span class="avatar candidate-avatar" style="background:${c.color}">${c.initials}</span><div class="candidate-row-info"><h3>${esc(c.id==='c1'?db.profile.name:c.name)} ${isSponsored?tag('Sponsorizzato','sponsored'):''}</h3><p>${esc(c.title)} · ${esc(c.city)}</p><div class="job-tags">${c.skills.map(s=>tag(s)).join('')}</div></div><div class="candidate-row-end"><span class="tag ${c.status==='Colloquio'?'match':''}">${esc(db.companyStatuses[c.id]||c.status)}</span><button class="icon-button" data-action="candidate" data-id="${c.id}" aria-label="Apri profilo di ${esc(c.name)}">${icon('arrow',20)}</button></div></article>`;}
function companyOffers(){const list=allJobs().filter(j=>j.company==='radice');return shell(`${pageHead('IL PRIMO INCONTRO È NELLE PAROLE.','Le tue <em>opportunità.</em>','Descrivi il lavoro con la chiarezza che vorresti trovare.',`<button class="button dark" data-action="new-offer">${icon('plus',17)} Nuova offerta</button>`)}<div class="company-offers-grid">${list.map(j=>`<article class="panel company-offer-card"><div class="job-card-top">${tag('Pubblicata','match')}<small>${j.id.startsWith('custom')?'Appena creata':'Aggiornata oggi'}</small></div><h2>${esc(j.title)}</h2><p>${esc(j.city)} · ${esc(j.mode)} · ${esc(j.contract)}</p><b>${money(j.salary[0])}–${money(j.salary[1])} € RAL</b><div class="offer-completeness"><span>${icon('check',16)} Condizioni in chiaro</span><span>${icon('check',16)} Percorso di crescita</span></div><div class="form-footer"><button class="text-button" data-action="preview-offer" data-id="${j.id}">Anteprima ${icon('eye',16)}</button><a class="button outline small" href="#/company/selections">Gestisci selezione ${icon('arrow',16)}</a></div></article>`).join('')}</div>`,'offers',true);}
function companyTalents(){const list=candidates.filter(c=>(c.id!=='c1'||db.profile.visible)&&norm(c.name+' '+c.skills.join(' ')).includes(norm(companyCandidateQuery)));const paid=list.filter(c=>c.sponsored||(c.id==='c1'&&db.boost));const ordinary=list.filter(c=>!paid.includes(c));return shell(`${pageHead('COMPETENZE CHE INCONTRANO POSSIBILITÀ.','Trova la tua prossima <em>connessione.</em>','Profili dimostrativi con esperienze e capacità leggibili.')}<label class="talent-search panel">${icon('search')}<input id="candidate-query" placeholder="Cerca per nome o competenza" value="${esc(companyCandidateQuery)}" aria-label="Cerca candidati"></label><div class="panel talent-list">${paid.length?`<div class="sponsored-band"><span class="eyebrow">IN EVIDENZA · PROFILI SPONSORIZZATI</span>${paid.map(candidateRow).join('')}</div>`:''}${list.length?ordinary.map(candidateRow).join(''):'<div class="empty-state"><h3>Nessun profilo per questa ricerca.</h3><p>Prova una competenza diversa.</p></div>'}</div><div class="info-note">${icon('shield',18)} I profili sponsorizzati sono riconoscibili. La maggiore visibilità non modifica le capacità o le valutazioni.</div>`,'talents',true);}
function companySelections(){const localStatus=db.applications.find(a=>a.jobId==='j1')?.status;return shell(`${pageHead('OGNI CANDIDATURA È UNA PERSONA.','Dai forma al tuo <em>prossimo team.</em>','Una selezione leggibile, dal primo contatto alla proposta.')}<div class="selection-tools"><label>Offerta<select id="company-job"><option value="j1">Junior UX/UI Designer</option><option value="j4" ${companyJob==='j4'?'selected':''}>Content & Social Media Specialist</option></select></label><button class="button outline small" data-action="feedback-summary">${icon('chart',17)} Feedback sulla selezione</button></div><div class="kanban">${['Da valutare','Colloquio','Proposta'].map(s=>{const list=candidates.filter(c=>(db.companyStatuses[c.id]||c.status)===s);return `<section class="kanban-column"><h3><span class="status-dot ${s==='Colloquio'?'lime-dot':''}"></span>${s}<span>${list.length}</span></h3>${list.map(c=>`<article class="panel kanban-card"><span class="avatar" style="background:${c.color}">${c.initials}</span><button class="icon-button" data-action="candidate" data-id="${c.id}" aria-label="Apri profilo">${icon('arrowUp',18)}</button><h4>${esc(c.name)}</h4><p>${esc(c.title)}</p><small>${esc(c.city)} · ${esc(c.experience)}</small><div class="job-tags">${c.skills.slice(0,2).map(s=>tag(s)).join('')}</div><label class="sr-only" for="status-${c.id}">Stato di ${esc(c.name)}</label><select id="status-${c.id}" class="candidate-status" data-id="${c.id}">${['Da valutare','Colloquio','Proposta','Assunta','Non selezionata'].map(t=>`<option ${t===s?'selected':''}>${t}</option>`).join('')}</select></article>`).join('')}${!list.length?'<div class="kanban-empty">Le nuove connessioni compariranno qui.</div>':''}</section>`}).join('')}</div><div class="info-note">${icon('shield',18)} Le variazioni sulla candidatura di Giulia sono visibili anche nella sua area. ${localStatus?'Stato corrente: '+esc(localStatus)+'.':''}</div><button class="text-button" data-action="employee-review">Apri la valutazione professionale a sei mesi</button>`,'selections',true);}
function companyBusiness(){const c=companies[0];return shell(`${pageHead('IL TUO MODO DI LAVORARE, IN CHIARO.','Le persone dietro <em>radice.</em>','Un profilo aziendale che racconta condizioni e possibilità.')}<div class="business-profile-grid"><form id="company-form" class="panel form-panel"><div class="job-card-top">${logo(c,'large')}<div><h2>radice studio</h2><p>Design & comunicazione · Salerno</p></div></div><label>La nostra storia<textarea name="about" rows="5">${esc(db.companyProfile.about)}</textarea></label><div class="form-grid"><label>Dipendenti nel perimetro<input value="24" disabled></label><label>Ultimo aggiornamento<input value="23 ottobre 2026 · dato demo" disabled></label></div><div class="job-tags">${c.benefits.map(t=>tag(t)).join('')}</div><div class="form-footer"><span class="small-copy">I dati dell’organico sono simulati e non verificati.</span><button class="button dark" type="submit">Salva ${icon('check',17)}</button></div></form><section class="panel company-heart-card"><span class="eyebrow">LE CONNESSIONI SI COLTIVANO.</span><div class="giant-heart" style="--fill:${Math.round((12+(db.heart?1:0))/24*100)}%">♥</div><h2>${Math.round((12+(db.heart?1:0))/24*100)}% di apprezzamenti</h2><p>${12+(db.heart?1:0)} like su 24 dipendenti.<br>16 dipendenti eleggibili noti alla demo.</p><button class="inline-link" data-action="heart-info" data-id="radice">Come si legge il cuore ${icon('arrow',17)}</button><small>Non misura la percentuale di persone soddisfatte. Identità individuali non mostrate.</small></section></div>`,'business',true);}

function render(){const r=route();if(r==='/')$('#app').innerHTML=landing();else if(r.startsWith('/job/'))$('#app').innerHTML=jobDetail(r.split('/')[2]);else if(r.startsWith('/company'))$('#app').innerHTML=companyPage(r.split('/')[2]||'overview');else if(r==='/profile')$('#app').innerHTML=profilePage();else if(r==='/applied')$('#app').innerHTML=applicationsPage();else if(r==='/messages')$('#app').innerHTML=messagesPage();else if(r==='/plus')$('#app').innerHTML=plusPage();else if(r==='/home')$('#app').innerHTML=homePage();else $('#app').innerHTML=jobsPage();document.title='MESH — '+(r==='/'?'Il tuo talento, la giusta connessione.':r.startsWith('/company')?'Spazio aziende':'Il tuo prossimo passo');bindForms();if($('#search-chat'))$('#search-chat').scrollTop=$('#search-chat').scrollHeight;const cb=$('.conversation-body');if(cb)cb.scrollTop=cb.scrollHeight;}

function showModal(title,body,wide=false){modal={title};$('#modal-root').innerHTML=`<div class="modal-overlay"><section class="modal ${wide?'modal-wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><header><div><span class="eyebrow">MESH / UNA CONNESSIONE ALLA VOLTA</span><h2 id="modal-title">${title}</h2></div><button class="icon-button" data-action="close-modal" aria-label="Chiudi">${icon('close',23)}</button></header><div class="modal-body">${body}</div></section></div>`;document.body.classList.add('modal-open');const focusable=$('#modal-root input, #modal-root textarea, #modal-root select, #modal-root button');focusable?.focus();bindForms();}
function closeModal(){modal=null;$('#modal-root').innerHTML='';document.body.classList.remove('modal-open');}
function showFeedback(id){const saved=db.feedbacks[id];showModal('La tua esperienza conta.',`<p class="muted">Feedback sulla selezione · 10 domande. Nella demo è compilabile subito. Le tempistiche definitive sono da confermare. Il singolo feedback è visibile alle parti, senza pubblicazione del nome.</p><form id="feedback-form" data-id="${id}"><div class="question-list">${selectionQuestions.map((q,i)=>`<label><span><small>${String(i+1).padStart(2,'0')}</small>${q}</span><select name="s${i}" required><option value="">Scegli una risposta</option>${['1 — Per niente','2 — Poco','3 — In parte','4 — Molto','5 — Del tutto','Non applicabile'].map(v=>`<option ${saved?.['s'+i]===v?'selected':''}>${v}</option>`).join('')}</select></label>`).join('')}<label><span><small>10</small>Quali aspetti dovrebbe migliorare l’azienda?</span><select name="improve" multiple size="5" aria-label="Aspetti da migliorare, selezione multipla"><option>Nessuno in particolare</option>${['Chiarezza dell’offerta','Comunicazione e tempi','Colloqui e prove','Coerenza delle condizioni','Crescita e benefit','Comunicazione dell’esito','Altro'].map(v=>`<option ${(saved?.improve||[]).includes(v)?'selected':''}>${v}</option>`).join('')}</select><textarea name="comment" rows="3" placeholder="Dettagli, episodi o suggerimenti (facoltativo)">${esc(saved?.comment||'')}</textarea></label></div><button class="button dark wide" type="submit">Salva il feedback ${icon('check',17)}</button></form>`,true);}
function showOfferForm(){showModal('La prossima connessione inizia qui.',`<form id="offer-form"><div class="form-grid"><label class="full">Titolo del ruolo<input name="title" placeholder="Es. Project Coordinator" required></label><label>Città<input name="city" value="Salerno" required></label><label>Modalità<select name="mode"><option>Ibrido</option><option>In sede</option><option>Remoto</option></select></label><label>RAL minima (€)<input name="min" type="number" min="1000" value="26000" required></label><label>RAL massima (€)<input name="max" type="number" min="1000" value="32000" required></label><label>Contratto<select name="contract"><option>Indeterminato</option><option>Apprendistato</option><option>Determinato</option></select></label><label>Ore settimanali<input name="hours" type="number" min="1" max="48" value="40" required></label><label class="full">Attività e responsabilità<textarea name="description" rows="3" required placeholder="Descrivi il lavoro concreto e l’autonomia richiesta"></textarea></label><label class="full">Orari e turni<input name="shift" value="Lun–ven, 9:00–18:00" required></label><label class="full">Competenze richieste, separate da virgole<input name="skills" placeholder="Organizzazione, Excel, Comunicazione" required></label><label class="full">Possibile ruolo successivo<input name="next" placeholder="Es. Senior Project Coordinator" required></label><label>Fascia RAL futura<input name="future" placeholder="32–38k €" required></label><label>Benefit / condizioni di accesso<input name="benefit" placeholder="Formazione, obiettivi concordati" required></label></div><label class="checkbox-label"><input name="weekend" type="checkbox"> Sono previsti turni nel weekend</label><p class="small-copy">Archivio demo. La proposta conserva condizioni e crescita come versione dell’offerta.</p><button class="button dark wide" type="submit">Pubblica nell’archivio demo ${icon('arrow',18)}</button></form>`,true);}
function showCandidate(id){const c=candidates.find(x=>x.id===id);if(!c)return;showModal(esc(c.name),`<div class="candidate-modal-header"><span class="avatar profile-avatar" style="background:${c.color}">${c.initials}</span><div><h3>${esc(c.title)}</h3><p>${esc(c.city)} · ${esc(c.experience)} di esperienza</p></div></div><h3>Capacità dichiarate</h3><div class="job-tags">${c.skills.map(s=>tag(s,'match')).join('')}</div><p>Profilo sintetico dimostrativo. Le capacità sono dichiarate; la demo non certifica competenze o documenti.</p><h3>Da approfondire insieme</h3><p>Esempi di progetti, autonomia sulle attività e disponibilità rispetto all’offerta. Un dato mancante non equivale a una capacità assente.</p><div class="button-group"><button class="button dark" data-action="contact-candidate" data-id="${id}">Apri conversazione ${icon('message',17)}</button><button class="button outline" data-action="schedule">Organizza incontro ${icon('clock',17)}</button></div>`);}
function showEmployment(){showModal('Come sta andando il tuo percorso?',`<div class="employment-banner">${logo(companies[0],'large')}<div><h3>radice studio</h3><p>Rapporto dimostrativo · 6 mesi di anzianità simulata</p></div></div><p>Puoi esprimere apprezzamento per il trattamento delle persone e il rispetto delle condizioni concordate. La scelta individuale non viene mostrata all’azienda.</p><button class="like-action ${db.heart?'liked':''}" data-action="toggle-heart"><span>♥</span>${db.heart?'Apprezzamento espresso · ritira':'Esprimi apprezzamento'}</button><div class="info-note">${icon('shield')} Qui il periodo è simulato. In produzione serviranno verifica del rapporto e aggregazione per proteggere l’identità, soprattutto nelle microimprese.</div>`);}
function showProfessional(){showModal('Una crescita che si costruisce insieme.',`<p>Valutazione professionale demo di ${esc(db.profile.name)} dopo sei mesi simulati. Visibile alle parti; nessuna reputazione pubblica automatica.</p><form id="professional-form"><div class="question-list">${professionalQuestions.map((q,i)=>`<label><span><small>${i+1}</small>${q}</span><select name="d${i}" required><option value="">Scegli una valutazione</option>${['1 — Raramente osservato','2 — Discontinuo','3 — Coerente con il ruolo','4 — Costante','5 — Contributo al miglioramento','Non osservabile'].map(v=>`<option ${db.professional['d'+i]===v?'selected':''}>${v}</option>`).join('')}</select></label>`).join('')}<label>Contesto e azioni di sviluppo<textarea name="context" rows="3">${esc(db.professional.context||'')}</textarea></label></div><button class="button dark wide" type="submit">Salva valutazione demo ${icon('check',17)}</button></form>`);}

async function searchChat(text){if(chatBusy)return;chatBusy=true;db.searchMessages.push({role:'user',text});save();let q=norm(text),next={...filters},notes=[];if(/ricomincia|azzera|tutte le offerte/.test(q))next={q:'',city:'',mode:'',contract:'',noWeekend:false,min:0};for(const c of ['Napoli','Salerno','Caserta','Avellino','Benevento'])if(q.includes(norm(c))){next.city=c;notes.push(c);}const mappings=[[/amministraz|contabil/,'Amministrazione'],[/design|figma/,'Design'],[/developer|svilupp|react|frontend/,'Developer'],[/marketing|social|content/,'Content'],[/ospital|accoglienz|hotel/,'accoglienza'],[/logistic|ordini|magazzino/,'ordini'],[/produzion|tecnico/,'produzione'],[/customer|clienti|assistenza/,'Customer']];for(const [rx,v]of mappings)if(rx.test(q)){next.q=v;notes.push('ruolo: '+v);break;}if(/remoto|remote/.test(q)){next.mode='Remoto';notes.push('remoto');}else if(/ibrid/.test(q)){if(/possibilmente|preferir|preferenza/.test(q))notes.push('ibrido come preferenza, non vincolo');else{next.mode='Ibrido';notes.push('ibrido');}}else if(/in sede|presenza/.test(q)){next.mode='In sede';notes.push('in sede');}if(/senza weekend|no weekend|niente weekend/.test(q)){next.noWeekend=true;notes.push('nessun weekend');}if(/indeterminat/.test(q)){next.contract='Indeterminato';notes.push('tempo indeterminato');}const amount=q.match(/(\d{2,3})\s*k\b/);if(amount&&/lord|ral/.test(q)){next.min=Number(amount[1])*1000;notes.push('RAL da '+money(next.min)+' €');}let response;if(/\b\d[\d.,]*\s*(euro|€)/.test(q)&&!/lord|ral/.test(q)){response='Per impostare il compenso mi serve un dettaglio: intendi una cifra lorda o netta, mensile o annuale? In questa demo posso confrontare solo la RAL dichiarata.';}else if(/oppure| o remoto|remote o/.test(q)){response='Hai indicato delle alternative. Per non trasformarle in vincoli sbagliati, scegliamo una prima ricerca: preferisci iniziare dal remoto oppure da una località?';}else if(notes.length){filters=next;const count=filteredJobs().length;response=`Ho interpretato: ${notes.join(' · ')}. ${count?`Trovi ${count} opportunità nei risultati.`:'Non trovo offerte con questi criteri. Puoi rimuovere un filtro: non cambio i tuoi vincoli da sola.'} Puoi correggere tutto dai filtri qui accanto.`;}else{response='In questa simulazione posso aiutarti con ruolo, città della Campania, modalità, contratto e disponibilità nel weekend. Per esempio: «Design a Salerno, senza weekend». Le qualità dell’ambiente vanno approfondite nelle informazioni aziendali.';}db.searchMessages.push({role:'assistant',text:response});save();chatBusy=false;render();}
function bindForms(){const bind=(s,f)=>{const el=$(s);if(el)el.onsubmit=e=>{e.preventDefault();f(new FormData(el),el)}};
 bind('#search-chat-form',fd=>searchChat(String(fd.get('message'))));
 bind('#profile-form',fd=>{for(const k of ['name','title','city','email','bio','experience','education'])db.profile[k]=String(fd.get(k));db.profile.skills=String(fd.get('skills')).split(',').map(s=>s.trim()).filter(Boolean);db.profile.visible=fd.has('visible');save();toast('Profilo aggiornato nell’archivio demo.');render();});
 bind('#cv-chat-form',fd=>{const story=String(fd.get('story')).trim();db.cvMessages.push(story);const known=['Figma','React','JavaScript','Python','Excel','Canva','Comunicazione','Organizzazione','Inglese','Contabilità','Prototipazione','Ricerca utente'];const found=known.filter(s=>norm(story).includes(norm(s)));let summary=story.replace(/\bmi chiamo [^,.]+[,.]?/i,'').replace(/\bsono appassionat[oa] di\b/gi,'Interesse per').replace(/\bho lavorato\b/gi,'Esperienza lavorativa').replace(/\bho studiato\b/gi,'Formazione in').replace(/\bmi occupo di\b/gi,'Attività nell’ambito di').trim();summary=summary.charAt(0).toUpperCase()+summary.slice(1);db.cvDraft={summary,skills:[...new Set([...db.profile.skills,...found])],aspirations:String(fd.get('aspirations')),salary:String(fd.get('salary')),availability:String(fd.get('availability'))};save();render();toast('Bozza demo creata. Rivedi ogni informazione prima di confermare.');});
 bind('#message-form',fd=>{const t=db.threads.find(t=>t.id===activeThread)||db.threads[0];t.messages.push({from:route().startsWith('/company')?'company':'candidate',text:String(fd.get('message')),time:new Date().toLocaleTimeString('it-IT',{hour:'2-digit',minute:'2-digit'})});save();render();});
 bind('#feedback-form',(fd,el)=>{const improvements=fd.getAll('improve');if(improvements.length>1&&improvements.includes('Nessuno in particolare'))return toast('Scegli gli aspetti da migliorare oppure Nessuno in particolare.');db.feedbacks[el.dataset.id]={...Object.fromEntries(fd),improve:improvements};save();closeModal();render();toast('Feedback demo salvato. Grazie per il tuo contributo.');});
 bind('#professional-form',fd=>{db.professional=Object.fromEntries(fd);save();closeModal();toast('Valutazione professionale demo salvata.');});
 bind('#company-form',fd=>{db.companyProfile.about=String(fd.get('about'));save();toast('Profilo aziendale aggiornato nella demo.');});
 bind('#schedule-form',fd=>{const event=Object.fromEntries(fd);db.calendar.push(event);db.threads[0].messages.push({from:'company',text:`Ti proponiamo un incontro il ${event.date} alle ${event.time}. ${event.note}`,time:new Date().toLocaleTimeString('it-IT',{hour:'2-digit',minute:'2-digit'})});save();closeModal();toast('Incontro salvato e proposta aggiunta alla conversazione demo.');render();});
 bind('#offer-form',fd=>{const min=Number(fd.get('min')),max=Number(fd.get('max'));if(max<min)return toast('La RAL massima deve essere almeno pari alla minima.');const skills=String(fd.get('skills')).split(',').map(s=>s.trim()).filter(Boolean);db.customJobs.unshift({id:'custom-'+Date.now(),company:'radice',title:String(fd.get('title')),category:'Altro',city:String(fd.get('city')),mode:String(fd.get('mode')),contract:String(fd.get('contract')),hours:Number(fd.get('hours')),salary:[min,max],benchmark:[min,max],weekend:fd.has('weekend'),level:'Da definire',skills,tags:['Nuova opportunità'],description:String(fd.get('description')),tasks:[String(fd.get('description'))],shift:String(fd.get('shift')),growth:[[String(fd.get('next')),String(fd.get('future')),String(fd.get('benefit'))]],posted:'Adesso'});save();closeModal();go('/company/offers');toast('Offerta pubblicata nell’archivio demo.');});
 const q=$('#job-query');if(q)q.oninput=()=>{filters.q=q.value;const pos=q.selectionStart;render();$('#job-query').focus();$('#job-query').setSelectionRange(pos,pos)};
 for(const [id,k]of [['job-city','city'],['job-mode','mode'],['job-contract','contract']]){const el=$('#'+id);if(el)el.onchange=()=>{filters[k]=el.value;render()};}
 const cq=$('#candidate-query');if(cq)cq.oninput=()=>{companyCandidateQuery=cq.value;const pos=cq.selectionStart;render();$('#candidate-query').focus();$('#candidate-query').setSelectionRange(pos,pos)};
 const cj=$('#company-job');if(cj)cj.onchange=()=>{companyJob=cj.value;toast('Selezione demo: il gruppo di profili è condiviso tra le offerte.');};
 document.querySelectorAll('.candidate-status').forEach(el=>el.onchange=()=>{db.companyStatuses[el.dataset.id]=el.value;if(el.dataset.id==='c1'){const a=db.applications.find(a=>a.jobId==='j1');if(a){a.status=el.value;a.history.push(el.value);}}save();render();toast('Stato aggiornato nell’archivio demo.');});
 const up=$('#cv-upload');if(up)up.onchange=async()=>{const f=up.files[0];if(!f)return;if(f.size>1000000)return toast('Per la demo usa un file di testo inferiore a 1 MB.');const txt=await f.text();const ta=$('#cv-chat-form [name="story"]');ta.value=txt;toast('Testo importato. Puoi rivederlo e creare la bozza.');};
}

document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action,id=el.dataset.id;if(el.tagName==='A'&&!['saved-link'].includes(a))e.preventDefault();switch(a){
 case'login':showModal('Da che parte vuoi connetterti?',`<p>Esplora MESH con un profilo dimostrativo. Non serve creare un account.</p><div class="login-options"><a class="login-option" href="#/jobs" data-action="enter-candidate">${icon('user',27)}<b>Cerco il mio prossimo lavoro</b><span>Entra nello spazio candidato ${icon('arrow',17)}</span></a><a class="login-option" href="#/company" data-action="enter-company">${icon('building',27)}<b>Cerco il prossimo talento</b><span>Entra nello spazio azienda ${icon('arrow',17)}</span></a></div><p class="small-copy">Accessi simulati: non è un sistema di autenticazione di produzione.</p>`);break;
 case'enter-candidate':closeModal();go('/jobs');break;case'enter-company':closeModal();go('/company');break;
 case'switch':go(route().startsWith('/company')?'/jobs':'/company');break;
 case'close-modal':closeModal();break;
 case'job-tab':jobTab=el.dataset.tab;render();break;case'profile-tab':profileTab=el.dataset.tab;go('/profile');break;case'app-tab':appTab=el.dataset.tab;render();break;
 case'saved-link':jobTab='saved';break;
 case'save-job':db.saved=db.saved.includes(id)?db.saved.filter(x=>x!==id):[...db.saved,id];save();render();toast(db.saved.includes(id)?'Offerta salvata. La ritrovi nella scheda Salvate.':'Offerta rimossa dai salvati.');break;
 case'hide-job':db.hidden=db.hidden.includes(id)?db.hidden.filter(x=>x!==id):[...db.hidden,id];save();go('/jobs');toast('Visibilità dell’offerta aggiornata.');break;
 case'weekend':filters.noWeekend=!filters.noWeekend;render();break;
 case'clear-min':filters.min=0;render();break;
 case'clear-filters':filters={q:'',city:'',mode:'',contract:'',noWeekend:false,min:0};render();break;
 case'mobile-chat':mobileChatOpen=!mobileChatOpen;render();break;
 case'clear-search':db.searchMessages=[];filters={q:'',city:'',mode:'',contract:'',noWeekend:false,min:0};save();render();break;
 case'suggest':searchChat(el.dataset.text);break;
 case'apply':{const j=job(id);showModal('Il primo passo, alle tue condizioni.',`<h3>${esc(j.title)}</h3><p>${esc(company(j.company).name)} ${esc(company(j.company).suffix)} · ${esc(j.city)}</p><div class="info-note">${icon('shield')} Condividerai il profilo approvato e conserverai le condizioni dell’offerta in questa candidatura demo.</div><p><b>CV:</b> ${esc(db.profile.name)} · ${esc(db.profile.title)}</p><p><b>RAL:</b> ${money(j.salary[0])}–${money(j.salary[1])} € · ${esc(j.contract)}</p><button class="button dark wide" data-action="confirm-apply" data-id="${id}">Conferma candidatura demo ${icon('arrow',17)}</button>`);break;}
 case'confirm-apply':{if(!db.applications.some(x=>x.jobId===id)){const j=job(id);db.applications.push({id:'a'+Date.now(),jobId:id,status:'Inviata',date:new Date().toISOString().slice(0,10),history:['Candidatura inviata'],offerSnapshot:structuredClone(j),cvSnapshot:structuredClone(db.profile)});if(!db.threads.some(t=>t.company===j.company))db.threads.push({id:'t'+Date.now(),company:j.company,messages:[{from:'candidate',text:`Ciao! Ho inviato la mia candidatura per ${j.title}. Mi piacerebbe approfondire questa opportunità.`,time:'Adesso'}]});save();}closeModal();render();toast('Candidatura inviata nell’archivio demo.');break;}
 case'view-application':go('/applied');break;
 case'withdraw':showModal('Vuoi ritirare questa candidatura?',`<p>La candidatura verrà archiviata. L’operazione riguarda solo l’archivio demo.</p><button class="button dark" data-action="confirm-withdraw" data-id="${id}">Conferma il ritiro</button>`);break;
 case'confirm-withdraw':db.applications.find(x=>x.id===id).status='Ritirata';save();closeModal();render();toast('Candidatura ritirata.');break;
 case'feedback':showFeedback(id);break;
 case'thread':activeThread=id;render();break;
 case'new-offer':showOfferForm();break;
 case'preview-offer':go('/job/'+id);break;
 case'candidate':showCandidate(id);break;
 case'contact-candidate':closeModal();if(id!=='c1')toast('Conversazione dimostrativa: usiamo il profilo di Giulia.');go('/company/messages');break;
 case'schedule':showModal('Un incontro per conoscersi.',`<form id="schedule-form"><div class="form-grid"><label>Data<input type="date" name="date" min="${new Date().toISOString().slice(0,10)}" required></label><label>Ora<input type="time" name="time" value="15:00" required></label><label class="full">Cosa approfondirete?<textarea name="note" rows="3" required>Un primo incontro sul ruolo, i progetti e le condizioni del lavoro.</textarea></label></div><button class="button dark wide" type="submit">Salva la proposta demo ${icon('arrow',17)}</button></form>`);break;
 case'feedback-summary':{const list=Object.values(db.feedbacks);showModal('Ascolta. Chiarisci. Migliora.',`<p>${list.length?`${list.length} feedback raccolti nell’archivio demo.`:'Non sono ancora stati raccolti feedback in questa demo.'}</p><p>La raccolta comprende 10 domande su chiarezza, comunicazione, colloqui, coerenza, crescita ed esito.</p><div class="info-note">${icon('shield')} Gli aggregati reali richiederanno un numero di contributi e regole di pubblicazione adeguati. Nessun voto viene inventato.</div><a class="button dark" href="#/applied" data-action="enter-feedback">Esplora il questionario candidato ${icon('arrow',17)}</a>`);break;}
 case'enter-feedback':closeModal();go('/applied');break;
 case'employee-review':showProfessional();break;
 case'employment':showEmployment();break;
 case'toggle-heart':db.heart=!db.heart;save();showEmployment();toast(db.heart?'Apprezzamento demo registrato.':'Apprezzamento demo ritirato.');break;
 case'heart-info':{const c=company(id),l=c.likes+(db.heart&&id==='radice'?1:0);showModal('Un cuore da leggere con contesto.',`<div class="heart-info-display">${heart(c)}</div><h3>${l} apprezzamenti / ${c.employees} dipendenti</h3><p>Il cuore mostra i like registrati rispetto all’organico. Gli eleggibili noti nella demo sono ${c.eligible}; chi non ha messo like non viene considerato insoddisfatto.</p><p>Organico, anzianità e apprezzamenti sono dati fittizi. La demo non garantisce l’anonimato di un sistema reale: prima dell’uso pubblico servono verifiche e aggregazioni che proteggano le persone.</p><small>Dati demo · ottobre 2026 · perimetro: singola azienda.</small>`);break;}
 case'learning':{const j=job(id);showModal('Un passo concreto verso il prossimo ruolo.',`<span class="tag match">LABORATORIO DIMOSTRATIVO</span><h3>Approfondire ${esc(j.skills[0])}</h3><p>Un esempio di percorso collegato alle capacità richieste da «${esc(j.title)}».</p><ul class="check-list"><li>${icon('check',17)} Raccogli un esempio pratico del tuo lavoro.</li><li>${icon('check',17)} Individua ciò che vorresti approfondire.</li><li>${icon('check',17)} Confrontati con l’azienda su affiancamento e formazione.</li></ul><div class="info-note">Il catalogo di corsi reali non è ancora collegato. Nessun seminario o certificato viene presentato come disponibile.</div>`);break;}
 case'save-cv':{const summary=$('#cv-summary')?.value||db.profile.bio;db.profile.bio=summary;if(db.cvDraft){db.profile.skills=db.cvDraft.skills;db.profile.aspirations=db.cvDraft.aspirations;db.profile.salary=db.cvDraft.salary;db.profile.availability=db.cvDraft.availability;}db.cvDraft=null;save();render();toast('CV approvato e salvato nella demo.');break;}
 case'print-cv':window.print();break;
 case'download-cv':{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify({profile:db.profile,draft:db.cvDraft},null,2)],{type:'application/json'}));a.download='mesh-cv.json';a.click();URL.revokeObjectURL(a.href);toast('Dati del CV esportati.');break;}
 case'public-profile':showModal('Quello che l’azienda può conoscere.',`<h3>${esc(db.profile.name)}</h3><p>${esc(db.profile.title)} · ${esc(db.profile.city)}</p><p>${esc(db.profile.bio)}</p><div class="job-tags">${db.profile.skills.map(s=>tag(s,'match')).join('')}</div><div class="info-note">${icon('shield')} ${db.profile.visible?'Profilo disponibile nella ricerca demo.':'Profilo riservato: questa è solo un’anteprima personale.'} Il racconto grezzo e le conversazioni con l’assistente non compaiono qui.</div>`);break;
 case'boost':db.boost=!db.boost;save();render();toast(db.boost?'MESH Plus attivato nella demo. Nessun addebito.':'Sponsorizzazione demo disattivata.');break;
 case'notifications':showModal('Le tue connessioni, aggiornate.',`<div class="notification-item">${logo(companies[0])}<div><b>Un primo incontro con radice.</b><p>La conversazione sul ruolo UX/UI Designer ti aspetta.</p><a class="inline-link" href="#/messages" data-action="open-messages">Apri messaggi ${icon('arrow',16)}</a></div></div><p class="small-copy">Notifica dimostrativa. Nessuna email o notifica esterna inviata.</p>`);break;
 case'open-messages':closeModal();go('/messages');break;
 case'reset':showModal('Riparti da una nuova connessione.',`<p>Ripristina profilo, offerte e conversazioni ai dati iniziali della demo. Le modifiche locali verranno rimosse.</p><button class="button dark" data-action="confirm-reset">Ripristina dati dimostrativi</button>`);break;
 case'confirm-reset':db=initialDB();save();filters={q:'',city:'',mode:'',contract:'',noWeekend:false,min:0};closeModal();render();toast('Archivio demo ripristinato.');break;
 case'about':showModal('MESH. Una rete di possibilità.',`<p>MESH rappresenta l’intreccio diretto tra impresa e talento. Una proposta nata per le PMI campane, con trasparenza e tutela del lavoratore al centro.</p><p>Questa prima versione dimostra i percorsi candidato e azienda. Profili, stipendi, recensioni e aziende sono fittizi. Accesso, AI e pagamenti reali saranno collegati nelle fasi successive.</p>`);break;
 }});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if(e.key==='Tab'&&modal){const items=[...document.querySelectorAll('#modal-root button,#modal-root a,#modal-root input,#modal-root textarea,#modal-root select')].filter(x=>!x.disabled);const first=items[0],last=items.at(-1);if(e.shiftKey&&document.activeElement===first){last?.focus();e.preventDefault()}else if(!e.shiftKey&&document.activeElement===last){first?.focus();e.preventDefault()}}});
document.addEventListener('click',e=>{if(e.target.classList.contains('modal-overlay'))closeModal();});
window.addEventListener('hashchange',()=>{closeModal();render();if(!['#companies','#candidates','#how'].includes(location.hash))window.scrollTo(0,0)});
// Landing anchors remain on the landing page rather than becoming SPA routes.
document.addEventListener('click',e=>{const link=e.target.closest('a[href="#companies"],a[href="#candidates"],a[href="#how"]');if(link){e.preventDefault();document.querySelector(link.getAttribute('href'))?.scrollIntoView({behavior:'smooth',block:'center'});}});
render();
